#!/bin/sh
# Install public neutral adapter and run a network-disabled public platform probe only.
set -eu
umask 077
base=/root/t44-r9/independent772
mkdir -p "$base/public"
base64 -d > "$base/public/LOAD_NEUTRAL_ADAPTER.py" <<'PUBLIC_LOAD_NEUTRAL_ADAPTER_py'

PUBLIC_LOAD_NEUTRAL_ADAPTER_py
base64 -d > "$base/public/LOAD_NEUTRAL_ENTRY.sh" <<'PUBLIC_LOAD_NEUTRAL_ENTRY_sh'

PUBLIC_LOAD_NEUTRAL_ENTRY_sh
chmod 700 "$base/public/LOAD_NEUTRAL_ADAPTER.py" "$base/public/LOAD_NEUTRAL_ENTRY.sh"
printf '%s  %s\n' \
  '7b785defc44c91754ec4ea5a25cc07edced3605a130f4436d68572d1aec1ba18' "$base/public/LOAD_NEUTRAL_ADAPTER.py" \
  '222d2065507f9054ec12dfa150329f991a6dd96a83e826d9902a1a405b61e377' "$base/public/LOAD_NEUTRAL_ENTRY.sh" | sha256sum -c -
sh "$base/public/LOAD_NEUTRAL_ENTRY.sh" capabilities
printf '%s\n' 'Public adapter installed; public platform check only. Neutral inputs unread; SUT NOT RUN.'
